define('models/target',['require','backbone','common/math/rectangle','constants'],function (require) {

    'use strict';

    //var _        = require('underscore');
    var Backbone = require('backbone');

    var Rectangle = require('common/math/rectangle');

    /**
     * Constants
     */
    var Constants = require('constants');
    var EPSILON = 0.0001; // A tolerance level for determining matching y values

    /**
     * A movable target object that detects collisions with projectiles
     */
    var Target = Backbone.Model.extend({

        defaults: {
            x: Constants.Target.DEFAULT_X,
            y: Constants.GROUND_Y,
            radius: Constants.Target.DEFAULT_RADIUS,
            collisionEnabled: true
        },

        initialize: function(attributes, options) {
            this._bounds = new Rectangle();

            this.on('change:radius change:x change:y', this.updateBounds);
            this.updateBounds();
        },

        updateBounds: function() {
            this._bounds.set(
                this.get('x') - this.get('radius'),
                this.get('y') + EPSILON,
                this.get('radius') * 2,
                EPSILON
            );
        },

        calculateCollision: function(projectile) {
            var collision = this._bounds.overlaps(projectile.bounds());
            if (collision) {
                this.trigger('collide', this, projectile);
                this.set('collisionEnabled', false);
            }
            return collision;
        },

        reset: function() {
            this.set('collisionEnabled', true);
        },

    }, Constants.Target);

    return Target;
});

define('models/david',['require','backbone','common/math/rectangle','constants'],function (require) {

    'use strict';

    var Backbone = require('backbone');

    var Rectangle = require('common/math/rectangle');

    /**
     * Constants
     */
    var Constants = require('constants');

    /**
     * A david statue that detects collisions with projectiles
     */
    var David = Backbone.Model.extend({

        defaults: {
            x: Constants.David.DEFAULT_X,
            y: Constants.GROUND_Y,
            height: Constants.David.HEIGHT,
            collisionEnabled: true,
            naked: false
        },

        initialize: function(attributes, options) {
            this._bounds = new Rectangle();

            this.on('change:height change:x change:y', this.updateBounds);
            this.updateBounds();
        },

        updateBounds: function() {
            this._bounds.set(
                David.BOUNDS_RELATIVE_TO_HEIGHT.x * this.get('height') + this.get('x'),
                David.BOUNDS_RELATIVE_TO_HEIGHT.y * this.get('height') + this.get('y'),
                David.BOUNDS_RELATIVE_TO_HEIGHT.w * this.get('height'),
                David.BOUNDS_RELATIVE_TO_HEIGHT.h * this.get('height')
            );
        },

        calculateCollision: function(projectile) {
            var collision = this._bounds.overlaps(projectile.bounds());
            if (collision) {
                this.trigger('collide', this, projectile);
                this.set('collisionEnabled', false);
                this.set('naked', true);
            }
            return collision;
        },

        reset: function() {
            this.set('collisionEnabled', true);
            this.set('naked', false);
        },

    }, Constants.David);

    return David;
});

define('models/simulation',['require','exports','module','underscore','common/simulation/simulation','models/cannon','models/projectile','models/trajectory','models/target','models/david','constants'],function (require, exports, module) {

    'use strict';

    var _ = require('underscore');

    var Simulation = require('common/simulation/simulation');

    var Cannon     = require('models/cannon');
    var Projectile = require('models/projectile');
    var Trajectory = require('models/trajectory');
    var Target     = require('models/target');
    var David      = require('models/david');

    /**
     * Constants
     */
    var Constants = require('constants');

    /**
     * Wraps the update function in 
     */
    var ProjectileMotionSimulation = Simulation.extend({

        defaults: _.extend(Simulation.prototype.defaults, {
            initialSpeed: 18, // m/s
            airResistanceEnabled: false,
            altitude: 0,
            currentProjectile: null, // Current projectile instance that is set for launch or is in motion
            currentTrajectory: null  // Current trajectory instance--not created until cannon is fired
        }),
        
        initialize: function(attributes, options) {
            Simulation.prototype.initialize.apply(this, [attributes, options]);

            /* We always keep a projectile object that sits and waits to be launched
             *   so that the user can modify the projectile's properties.
             */   
            this.set('currentProjectile', new Projectile());

            this.on('change:altitude', function() {
                if (this.get('currentTrajectory'))
                    this.get('currentTrajectory').set('altitude', this.get('altitude'));
            });
            this.on('change:airResistanceEnabled', function() {
                if (this.get('currentTrajectory'))
                    this.get('currentTrajectory').set('airResistanceEnabled', this.get('airResistanceEnabled'));
            });
        },

        /**
         * Initializes the models used in the simulation
         */
        initComponents: function() {
            var cannon = new Cannon({
                x:     Constants.Cannon.START_X,
                y:     Constants.Cannon.START_Y,
                angle: Constants.Cannon.START_ANGLE
            });
            this.cannon = cannon;

            this.target = new Target();
            this.david  = new David();

            this.collisionObjects = [
                this.target,
                this.david
            ];
        },

        _update: function(time, deltaTime) {
            if (this.get('currentTrajectory'))
                this.get('currentTrajectory').update(time, deltaTime);
        },

        fireCannon: function() {
            // Abort any currently running trajectories
            if (this.get('currentTrajectory'))
                this.get('currentTrajectory').abort();

            var trajectory = new Trajectory({
                projectile: this.get('currentProjectile'),
                initialSpeed: this.get('initialSpeed'),
                initialAngle: -this.cannon.firingAngle(),
                initialX: this.cannon.firingX(),
                initialY: this.cannon.firingY(),
                airResistanceEnabled: this.get('airResistanceEnabled'),
                altitude: this.get('altitude'),
                collisionObjects: this.collisionObjects
            });
            this.set('currentTrajectory', trajectory);

            this.listenTo(trajectory, 'finish', function() {
                // Stop listening and forget trajectory
                this.stopListening(trajectory);
                this.set('currentTrajectory', null);

                // Make a new projectile and ready it for launch
                var newProjectile = this.get('currentProjectile').clone();
                newProjectile.reset();
                this.set('currentProjectile', newProjectile);
            });

            this.trigger('projectile-launched', this.get('currentProjectile'));

            trajectory.start();
            this.cannon.fire();
        }

    });

    return ProjectileMotionSimulation;
});

