define('text!templates/sim.html',[],function () { return '\r\n<span class="scene-view-placeholder"></span>\r\n\r\n<div class="trajectory-stats">\r\n    <h2>Shot Stats</h2>\r\n\r\n    <div class="stat-group">\r\n        <label for="range" class="control-label">Range (m)</label>\r\n        <input type="number" class="form-control" id="range" disabled="disabled">\r\n    </div>\r\n\r\n    <div class="stat-group">\r\n        <label for="height" class="control-label">Height (m)</label>\r\n        <input type="number" class="form-control" id="height" disabled="disabled">\r\n    </div>\r\n\r\n    <div class="stat-group">\r\n        <label for="time" class="control-label">Time (s)</label>\r\n        <input type="number" class="form-control" id="time" disabled="disabled">\r\n    </div>\r\n</div>\r\n    \r\n<div class="sim-controls">\r\n\r\n    <h2>Shot Parameters</h2>\r\n\r\n    <select class="form-control" id="projectile">\r\n    <% _.each(Constants.Projectiles, function(projectile, index) { %>\r\n        <option value="<%= index %>"><%= projectile.getName() %></option>\r\n    <% }); %>\r\n    </select>\r\n\r\n    <div class="control-group">\r\n        <label for="angle" class="control-label">Angle (degrees)</label>\r\n        <div class="input-wrapper">\r\n            <input type="number" min="<%= Constants.Cannon.MIN_ANGLE %>" max="<%= Constants.Cannon.MAX_ANGLE %>" class="form-control" id="angle" value="<%= simulation.cannon.get(\'angle\') %>">\r\n        </div>\r\n    </div>\r\n\r\n    <div class="control-group">\r\n        <label for="speed" class="control-label">Initial speed (m/s)</label>\r\n        <div class="input-wrapper">\r\n            <input type="number" min="0" class="form-control" id="speed" value="<%= simulation.get(\'initialSpeed\') %>">\r\n        </div>\r\n    </div>\r\n\r\n    <div class="control-group">\r\n        <label for="mass" class="control-label">Mass (kg)</label>\r\n        <div class="input-wrapper">\r\n            <input type="number" min="0" class="form-control" id="mass" value="<%= simulation.get(\'currentProjectile\').get(\'mass\') %>">\r\n        </div>\r\n    </div>\r\n\r\n    <div class="control-group">\r\n        <label for="diameter" class="control-label">Diameter (m)</label>\r\n        <div class="input-wrapper">\r\n            <input type="number" min="0" class="form-control" id="diameter" value="<%= simulation.get(\'currentProjectile\').get(\'diameter\') %>">\r\n        </div>\r\n    </div>\r\n\r\n    <input type="checkbox" id="air-resistance-check">\r\n    <label for="air-resistance-check" class="air-resistance-check">Air resistance</label><br>\r\n\r\n    <div class="air-resistance-parameters">\r\n        <div class="control-group">\r\n            <label for="drag" class="control-label">Drag Coefficient</label>\r\n            <div class="input-wrapper">\r\n                <input type="number" min="0" class="form-control" id="drag" value="<%= simulation.get(\'currentProjectile\').get(\'dragCoefficient\') %>">\r\n            </div>\r\n        </div>\r\n\r\n        <div class="control-group">\r\n            <label for="altitude" class="control-label">Altitude (m)</label>\r\n            <div class="input-wrapper">\r\n                <input type="number" class="form-control" id="altitude" value="<%= simulation.get(\'altitude\') %>">\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <button class="btn btn-fire">Fire!</button>\r\n    <button class="btn btn-erase">Erase</button>\r\n</div>\r\n\r\n<div class="sound-btn-wrapper">\r\n    <button class="sound-btn sound-btn-mute" title="Mute effect volume (click to raise)"><span class="fa fa-volume-off"></span></button>\r\n    <button class="sound-btn sound-btn-low"  title="Low effect volume (click to raise)"><span class="fa fa-volume-down"></span></button>\r\n    <button class="sound-btn sound-btn-high" title="High effect volume (click to mute)"><span class="fa fa-volume-up"></span></button>\r\n</div>\r\n\r\n<div class="zoom-controls">\r\n    <button class="btn btn-zoom-in"><span class="fa fa-search"><span class="fa fa-plus"></span></span></button>\r\n    <button class="btn btn-zoom-out"><span class="fa fa-search"><span class="fa fa-minus"></span></span></button>\r\n</div>\r\n\r\n<div class="score-indicator">\r\n    <span>Score!</span>\r\n</div>';});

